#include "group_journey_funding_codec.hpp"
#include "movement_exact_detail.hpp"
#include "resident/domains/actor_foundation/actor_foundation_json_visitor.hpp"
#include "resident/checkpoint/projection_record_archive.hpp"
namespace hanmo::resident {namespace funding_codec {
template<class C>Status military(C& c,MilitaryMarchExpenseAuthority& v){c.object("accepted_order_source",[&](auto& x){x.field("domain",v.accepted_order_source.domain);x.field("kind",v.accepted_order_source.kind);return x.field("id",v.accepted_order_source.id);});c.field("army_id",v.army_id);c.field("campaign_id",v.campaign_id);return c.field("payer_wallet_id",v.payer_wallet_id);}
}
Status visit_group_journey_funding(CodecVisitor& c,GroupJourneyFunding& v){Integer tag=Integer(v.index());c.field("funding_kind",tag);if(tag<0||tag>1)return c.reject("InvalidGroupJourneyFunding");if(c.reading()){if(tag==0)v.emplace<TransportExpenseAuthority>();else v.emplace<MilitaryMarchExpenseAuthority>();}return c.object("authority",[&](auto& x){return tag==0?visit_transport_expense_authority(x,std::get<TransportExpenseAuthority>(v)):funding_codec::military(x,std::get<MilitaryMarchExpenseAuthority>(v));});}
Outcome<GroupJourneyFunding> decode_group_journey_funding(const BoundaryValue& input){return movement_detail::guard<GroupJourneyFunding>([&]{const auto* d=input.as<BoundaryValue::Dict>();if(!d||d->size()!=2||(*d)[0].first!="funding_kind"||(*d)[1].first!="authority")movement_detail::fail("InvalidGroupJourneyFundingFields");const auto* tag=(*d)[0].second.as<Integer>();if(!tag||*tag<0||*tag>1)movement_detail::fail("InvalidGroupJourneyFunding");if(*tag==0)return GroupJourneyFunding{movement_detail::take(decode_transport_expense_authority((*d)[1].second))};MilitaryMarchExpenseAuthority v;ActorFoundationJsonVisitor c((*d)[1].second);movement_detail::take(funding_codec::military(c,v));movement_detail::take(c.finish());return GroupJourneyFunding{std::move(v)};});}
Status emit_group_journey_funding_fields(ProjectionWriter& x,const GroupJourneyFunding& v){x.field("funding_kind",Integer(v.index()));if(const auto* original=std::get_if<TransportExpenseAuthority>(&v))return emit_transport_expense_authority_projection(x,"authority",*original);return emit_projection_record<ActorFoundationProjectionArchive>(x,"authority",std::get<MilitaryMarchExpenseAuthority>(v),[](auto& c,auto& row){return funding_codec::military(c,row);});}
Status emit_group_journey_funding(ProjectionWriter& w,std::string_view name,const GroupJourneyFunding& v){return w.object(name,[&](auto& x){return emit_group_journey_funding_fields(x,v);});}
Outcome<BoundaryValue> encode_group_journey_funding(const GroupJourneyFunding& v){return movement_detail::guard<BoundaryValue>([&]{BoundaryValue out;BoundaryProjectionWriter w(out);movement_detail::take(emit_group_journey_funding(w,"",v));movement_detail::take(w.finish());return out;});}
}
